        "value": "A",
        "text": "Torque must satisfy equilibrium"
      },
      {
        "value": "B",
        "text": "Stress remains proportional to torque in linear elasticity"
      },
      {
        "value": "C",
        "text": "Shear modulus affects twist"
      },
      {
        "value": "D",
        "text": "Cross-sections remain plane without warping"
      }
    ],
    "correct_answer": "D",
    "explanation": "Noncircular sections generally warp. The circular formula tau=Tr/J cannot be transferred unchanged to rectangles."
  },
  {
    "display_order": 149,
    "question_text": "[Hydrology & Irrigation Engineering] A double-mass curve changes slope from 1.20 in the reliable period to 0.90 in the inconsistent period. To adjust an inconsistent recorded annual total of 600 mm to the reliable regime, use:",
    "options": [
      {
        "value": "A",
        "text": "675 mm"
      },
      {
        "value": "B",
        "text": "600 mm"
      },
      {
        "value": "C",
        "text": "800 mm"
      },
      {
        "value": "D",
        "text": "450 mm"
      }
    ],
    "correct_answer": "C",
    "explanation": "Correction factor is reliable slope/inconsistent slope=1.20/0.90. Adjusted rainfall=600x4/3=800 mm."
  },
  {
    "display_order": 150,
    "question_text": "[RCC Design] For this problem adopt e_min=L/500+D/30, but not less than 20 mm. A column has unsupported length 4000 mm and depth 600 mm. Required minimum eccentricity is:",
    "options": [
      {
        "value": "A",
        "text": "8 mm"
      },
      {
        "value": "B",
        "text": "28 mm"
      },
      {
        "value": "C",
        "text": "20 mm"
      },
      {
        "value": "D",
        "text": "48 mm"
      }
    ],
    "correct_answer": "B",
    "explanation": "L/500=8 and D/30=20, summing to 28 mm, which exceeds the 20 mm floor."
  }
]
$questions$::JSONB;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('TGPSC AEE 2026 - Civil Engineering Full Length Mock 01'));
 SELECT id INTO v_branch FROM public.engineering_branches WHERE name='Civil Engineering';
 IF v_branch IS NULL THEN
  INSERT INTO public.engineering_branches(name,code,description,is_active)
  VALUES('Civil Engineering','AEE26-'||substr(gen_random_uuid()::TEXT,1,8),'AEE practice catalogue',TRUE) RETURNING id INTO v_branch;
 END IF;
 INSERT INTO public.subjects(branch_id,name,code,description,display_order,is_active)
 VALUES(v_branch,'Civil Engineering','AEE26-'||substr(gen_random_uuid()::TEXT,1,8),'Separate full-length AEE practice paper',0,TRUE)
 ON CONFLICT(branch_id,name) DO NOTHING;
 SELECT id INTO v_subject FROM public.subjects WHERE branch_id=v_branch AND name='Civil Engineering';
 IF (SELECT count(*) FROM public.mock_tests WHERE title='TGPSC AEE 2026 - Civil Engineering Full Length Mock 01')>1 THEN
  RAISE EXCEPTION 'Duplicate test titles require manual resolution';
 END IF;
 SELECT id INTO v_test FROM public.mock_tests WHERE title='TGPSC AEE 2026 - Civil Engineering Full Length Mock 01';
 IF v_test IS NULL THEN
  INSERT INTO public.mock_tests(title,description,exam_type,subject_id,duration_minutes,total_marks,passing_marks,is_published)
  VALUES('TGPSC AEE 2026 - Civil Engineering Full Length Mock 01','Original unofficial Paper II Civil practice draft: 150 questions, 150 minutes, 300 marks. Separate paper and timer. Practice scoring +2 correct, 0 wrong/unanswered; this is not a verified 2026 penalty rule. Provisional syllabus reference; applicable AEE-specific 2026 notification and marking require verification. Passing marks 0 is a schema placeholder, not an official cutoff. Unpublished pending independent content review.','OTHER',v_subject,150,300,0,FALSE) RETURNING id INTO v_test;
  v_new := TRUE;
 ELSE
  IF EXISTS(SELECT 1 FROM public.mock_tests WHERE id=v_test AND
    (duration_minutes IS DISTINCT FROM 150 OR total_marks IS DISTINCT FROM 300 OR subject_id IS DISTINCT FROM v_subject))
   OR (SELECT count(*) FROM public.mock_questions WHERE mock_test_id=v_test)<>150
   OR EXISTS(SELECT 1 FROM public.mock_questions e LEFT JOIN jsonb_to_recordset(v_seed)
    AS q(display_order INT,question_text TEXT,options JSONB,correct_answer TEXT,explanation TEXT)
    ON e.display_order=q.display_order WHERE e.mock_test_id=v_test AND
    (q.display_order IS NULL OR e.question_text IS DISTINCT FROM q.question_text
     OR e.options IS DISTINCT FROM q.options OR e.correct_answer IS DISTINCT FROM q.correct_answer
     OR e.explanation IS DISTINCT FROM q.explanation OR e.question_type IS DISTINCT FROM 'mcq'
     OR e.marks IS DISTINCT FROM 2 OR e.negative_marks IS DISTINCT FROM 0)) THEN
   RAISE EXCEPTION 'Existing mock differs from seed; refusing to overwrite questions or attempt history';
  END IF;
 END IF;
 IF v_new THEN
  -- Live exact-text guard. Semantic/template novelty still requires human review.
  IF EXISTS(SELECT 1 FROM public.mock_questions e JOIN jsonb_to_recordset(v_seed)
   AS q(question_text TEXT) ON
   regexp_replace(lower(regexp_replace(e.question_text,'^\[[^]]+\]\s*','')),'[^a-z0-9]+',' ','g') =
   regexp_replace(lower(regexp_replace(q.question_text,'^\[[^]]+\]\s*','')),'[^a-z0-9]+',' ','g')) THEN
   RAISE EXCEPTION 'An existing database question matches this draft; review duplicates before importing';
  END IF;
  INSERT INTO public.mock_questions(mock_test_id,question_text,question_type,options,correct_answer,explanation,marks,negative_marks,display_order)
  SELECT v_test,q.question_text,'mcq',q.options,q.correct_answer,q.explanation,2,0,q.display_order
  FROM jsonb_to_recordset(v_seed) AS q(display_order INT,question_text TEXT,options JSONB,correct_answer TEXT,explanation TEXT);
 END IF;
 IF (SELECT count(*) FROM public.mock_questions WHERE mock_test_id=v_test)<>150
  OR (SELECT count(DISTINCT display_order) FROM public.mock_questions WHERE mock_test_id=v_test)<>150
  OR (SELECT sum(marks) FROM public.mock_questions WHERE mock_test_id=v_test)<>300 THEN
  RAISE EXCEPTION 'Invalid question count, display order or marks';
 END IF;
 RAISE NOTICE 'Separate AEE practice draft ready; publication status was not changed on repeat imports.';
END;
$seed$;

COMMIT;
